def P(txt, style='Bodyx'): return Paragraph(txt, styles[style])
def bullets(items): return [P('&bull;&nbsp; '+x) for x in items]
def numbered(items): return [P(f'{i}.&nbsp; {x}') for i,x in enumerate(items,1)]
def grid(rows, widths, header=True):
    data=[]
    for ri,row in enumerate(rows):
        data.append([P(str(c), 'CellHeadx' if header and ri==0 else 'Cellx') for c in row])
    t=Table(data,colWidths=widths,repeatRows=1 if header else 0,hAlign='LEFT')
    cmds=[('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.35,HexColor('#B9C9D1')),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]
    if header: cmds.append(('BACKGROUND',(0,0),(-1,0),NAVY))
    for i in range(1 if header else 0,len(rows)):
        if i%2: cmds.append(('BACKGROUND',(0,i),(-1,i),HexColor('#F4F8FA')))
    t.setStyle(TableStyle(cmds)); return t

def footer(canvas,doc):
    canvas.saveState(); w,h=A4
    if doc.page>1:
        canvas.setStrokeColor(HexColor('#D7E1E6')); canvas.line(20*mm,16*mm,w-20*mm,16*mm)
        canvas.setFont('Helvetica',8); canvas.setFillColor(HexColor('#587080'))
        canvas.drawString(20*mm,11*mm,'DSATM | Information and Network Security | 2025-2026')
        canvas.drawRightString(w-20*mm,11*mm,str(doc.page))
    canvas.restoreState()

